  if (typeof Noodl === 'undefined' || typeof Noodl.defineReactNode !== 'function') return;
  if (typeof NodeGXTipTap === 'undefined' || typeof React === 'undefined') return;

  var STYLE_ID = 'nodegx-richtext-style';
  var CSS = [
    '.nodegx-richtext{display:flex;flex-direction:column;width:100%;height:100%;min-height:120px;border:1px solid var(--border);border-radius:6px;background:var(--background);color:var(--foreground);}',
    '.nodegx-richtext__toolbar{display:flex;flex-wrap:wrap;gap:2px;padding:4px;border-bottom:1px solid var(--border);background:var(--muted);border-radius:6px 6px 0 0;}',
    '.nodegx-richtext__btn{border:1px solid transparent;background:transparent;color:var(--muted-foreground);border-radius:4px;min-width:26px;height:26px;padding:0 7px;font:inherit;font-size:13px;line-height:1;cursor:pointer;}',
    '.nodegx-richtext__btn:hover{background:var(--surface-raised);color:var(--foreground);}',
    '.nodegx-richtext__btn.is-active{background:var(--primary);color:var(--primary-foreground);}',
    '.nodegx-richtext__btn:disabled{opacity:0.4;cursor:default;}',
    '.nodegx-richtext__sep{width:1px;align-self:stretch;margin:2px 3px;background:var(--border);}',
    '.nodegx-richtext__content{flex:1 1 auto;overflow:auto;padding:8px 12px;}',
    '.nodegx-richtext__content .tiptap{outline:none;min-height:80px;}',
    '.nodegx-richtext__content .tiptap p.is-editor-empty:first-child::before{content:attr(data-placeholder);color:var(--muted-foreground);float:left;height:0;pointer-events:none;}',
    '.nodegx-richtext__content .tiptap a{color:var(--primary);text-decoration:underline;}',
    '.nodegx-richtext__content .tiptap blockquote{border-left:3px solid var(--border);margin:4px 0;padding-left:12px;color:var(--muted-foreground);}',
    '.nodegx-richtext__content .tiptap pre{background:var(--muted);border-radius:4px;padding:8px;overflow:auto;}',
    '.nodegx-richtext__content .tiptap code{background:var(--muted);border-radius:3px;padding:1px 4px;}'
  ].join('\n');

  function ensureStyles() {
    if (typeof document === 'undefined') return;
    if (document.getElementById(STYLE_ID)) return;
    var el = document.createElement('style');
    el.id = STYLE_ID;
    el.textContent = CSS;
    (document.head || document.documentElement).appendChild(el);
  }

  // Toolbar spec. Every callback guards against a missing editor.
  var TOOLBAR = [
    {
      key: 'bold', label: 'B', title: 'Bold',
      run: function (ed) { ed.chain().focus().toggleBold().run(); },
      active: function (ed) { return ed.isActive('bold'); }
    },
    {
      key: 'italic', label: 'I', title: 'Italic',
      run: function (ed) { ed.chain().focus().toggleItalic().run(); },
      active: function (ed) { return ed.isActive('italic'); }
    },
    { key: 'sep1', separator: true },
    {
      key: 'h1', label: 'H1', title: 'Heading 1',
      run: function (ed) { ed.chain().focus().toggleHeading({ level: 1 }).run(); },
      active: function (ed) { return ed.isActive('heading', { level: 1 }); }
    },
    {
      key: 'h2', label: 'H2', title: 'Heading 2',
      run: function (ed) { ed.chain().focus().toggleHeading({ level: 2 }).run(); },
      active: function (ed) { return ed.isActive('heading', { level: 2 }); }
    },
    {
      key: 'h3', label: 'H3', title: 'Heading 3',
      run: function (ed) { ed.chain().focus().toggleHeading({ level: 3 }).run(); },
      active: function (ed) { return ed.isActive('heading', { level: 3 }); }
    },
    { key: 'sep2', separator: true },
    {
      key: 'bullet', label: '• List', title: 'Bullet list',
      run: function (ed) { ed.chain().focus().toggleBulletList().run(); },
      active: function (ed) { return ed.isActive('bulletList'); }
    },
    {
      key: 'ordered', label: '1. List', title: 'Ordered list',
      run: function (ed) { ed.chain().focus().toggleOrderedList().run(); },
      active: function (ed) { return ed.isActive('orderedList'); }
    },
    { key: 'sep3', separator: true },
    {
      key: 'link', label: 'Link', title: 'Add or edit link (empty URL removes it)',
      run: function (ed) {
        if (typeof window === 'undefined' || typeof window.prompt !== 'function') return;
        var attrs = ed.getAttributes('link') || {};
        var url = window.prompt('Link URL', attrs.href || '');
        if (url === null) return; // cancelled
        if (url === '') {
          ed.chain().focus().extendMarkRange('link').unsetLink().run();
          return;
        }
        ed.chain().focus().extendMarkRange('link').setLink({ href: url }).run();
      },
      active: function (ed) { return ed.isActive('link'); }
    },
    { key: 'sep4', separator: true },
    {
      key: 'undo', label: '↶', title: 'Undo',
      run: function (ed) { ed.chain().focus().undo().run(); },
      disabled: function (ed) { return !ed.can().undo(); }
    },
    {
      key: 'redo', label: '↷', title: 'Redo',
      run: function (ed) { ed.chain().focus().redo().run(); },
      disabled: function (ed) { return !ed.can().redo(); }
    }
  ];

